def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    op_defects = op.count('D')
    my_defects = my.count('D')

    if n >= 10 and op_defects > 0.7 * n:
        return 'D'

    if op_defects == 0:
        return 'C'

    recent_op = op[-10:] if n >= 10 else op
    recent_d = recent_op.count('D')

    if last_my == 'D' and last_op == 'D':
        dd = 0
        for m, o in reversed(history):
            if m == 'D' and o == 'D':
                dd += 1
            else:
                break
        if dd >= 3:
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    if last_op == 'D' and last_my == 'C':
        if len(my) >= 2 and my[-2] == 'D':
            return 'C'
        if recent_d >= 3:
            return 'D'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    if last_op == 'C' and last_my == 'D':
        return 'C'

    return 'C'
